import{_ as r,C as t,o as s,c as l,j as a,a as h,G as i,a3 as d}from"./chunks/framework.B6x8LOwa.js";const b=JSON.parse('{"title":"FAQ","description":"Frequently asked questions about ICC-CE, covering installation, runtime, PPT integration, ink, performance, and more","frontmatter":{"title":"FAQ","description":"Frequently asked questions about ICC-CE, covering installation, runtime, PPT integration, ink, performance, and more"},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md"}'),u={name:"en/guide/faq.md"};function c(g,e,p,m,f,k){const n=t("ArticleMetadata"),o=t("KnownBugs");return s(),l("div",null,[e[0]||(e[0]=a("h1",{id:"faq",tabindex:"-1"},[h("FAQ "),a("a",{class:"header-anchor",href:"#faq","aria-label":'Permalink to "FAQ"'},"​")],-1)),i(n),i(o),e[1]||(e[1]=d('<h2 id="installation-runtime" tabindex="-1">Installation &amp; Runtime <a class="header-anchor" href="#installation-runtime" aria-label="Permalink to &quot;Installation &amp; Runtime&quot;">​</a></h2><h3 id="program-won-t-start-missing-net-runtime" tabindex="-1">Program won&#39;t start, missing .NET runtime <a class="header-anchor" href="#program-won-t-start-missing-net-runtime" aria-label="Permalink to &quot;Program won&#39;t start, missing .NET runtime&quot;">​</a></h3><p>ICC-CE requires .NET 6 Desktop Runtime. Search for &quot;.NET Desktop Runtime 6.x&quot; on Microsoft&#39;s official website and download the appropriate architecture (x64 / x86). The installer will prompt you to download it automatically when needed.</p><h3 id="portable-version-won-t-start" tabindex="-1">Portable version won&#39;t start <a class="header-anchor" href="#portable-version-won-t-start" aria-label="Permalink to &quot;Portable version won&#39;t start&quot;">​</a></h3><p>Most likely due to missing .NET 6 Desktop Runtime — install it as described above. If the runtime is already installed, check if the downloaded archive is intact and try extracting again.</p><h3 id="installer-says-cannot-install" tabindex="-1">Installer says &quot;Cannot install&quot; <a class="header-anchor" href="#installer-says-cannot-install" aria-label="Permalink to &quot;Installer says &quot;Cannot install&quot;&quot;">​</a></h3><p>Your system version may be too old. Make sure Windows 10 version ≥ 1809 (build 17763). It could also be antivirus software falsely flagging the installer — add ICC-CE to the whitelist.</p><h3 id="has-stopped-working-error-during-runtime" tabindex="-1">&quot;Has stopped working&quot; error during runtime <a class="header-anchor" href="#has-stopped-working-error-during-runtime" aria-label="Permalink to &quot;&quot;Has stopped working&quot; error during runtime&quot;">​</a></h3><ol><li>Check if the system version meets requirements</li><li>Try running as administrator</li><li>Check the log file (<code>%AppData%\\InkCanvasForClass CE\\Logs\\</code>) for detailed error information</li><li>If crashes persist, submit a GitHub Issue with the logs attached</li></ol><h2 id="ppt-integration" tabindex="-1">PPT Integration <a class="header-anchor" href="#ppt-integration" aria-label="Permalink to &quot;PPT Integration&quot;">​</a></h2><h3 id="doesn-t-auto-enter-annotation-mode-when-entering-ppt-slideshow" tabindex="-1">Doesn&#39;t auto-enter annotation mode when entering PPT slideshow <a class="header-anchor" href="#doesn-t-auto-enter-annotation-mode-when-entering-ppt-slideshow" aria-label="Permalink to &quot;Doesn&#39;t auto-enter annotation mode when entering PPT slideshow&quot;">​</a></h3><ol><li>Make sure PowerPoint is activated, not in protected view / read-only mode</li><li>Check that PPT integration is enabled in ICC-CE settings (enabled by default)</li><li>Check if PowerPoint is running as administrator while ICC-CE is not elevated — mismatched permissions prevent integration</li><li>Try switching integration modes (COM / ROT / Agent)</li></ol><h3 id="annotated-ink-can-t-be-found-after-saving" tabindex="-1">Annotated ink can&#39;t be found after saving <a class="header-anchor" href="#annotated-ink-can-t-be-found-after-saving" aria-label="Permalink to &quot;Annotated ink can&#39;t be found after saving&quot;">​</a></h3><p>Default save location: <code>%AppData%\\InkCanvasForClass CE\\Saves\\</code>. You can customize the save path in settings, or enable auto-rename on save to avoid overwriting.</p><h3 id="ink-lost-when-switching-slides" tabindex="-1">Ink lost when switching slides <a class="header-anchor" href="#ink-lost-when-switching-slides" aria-label="Permalink to &quot;Ink lost when switching slides&quot;">​</a></h3><p>Make sure &quot;Show Canvas on New Slide&quot; is enabled, and &quot;Hide Ink on Exit&quot; is enabled. When you return to an annotated page, the ink should be restored automatically.</p><h3 id="wps-integration-not-working" tabindex="-1">WPS integration not working <a class="header-anchor" href="#wps-integration-not-working" aria-label="Permalink to &quot;WPS integration not working&quot;">​</a></h3><p>Enable &quot;WPS Support&quot; in settings, and make sure WPS is not running as administrator.</p><h2 id="ink-handwriting" tabindex="-1">Ink &amp; Handwriting <a class="header-anchor" href="#ink-handwriting" aria-label="Permalink to &quot;Ink &amp; Handwriting&quot;">​</a></h2><h3 id="ink-latency-lag" tabindex="-1">Ink latency / lag <a class="header-anchor" href="#ink-latency-lag" aria-label="Permalink to &quot;Ink latency / lag&quot;">​</a></h3><ol><li>Disable hardware acceleration (Settings → Canvas &amp; Ink → Advanced Strokes → Hardware Acceleration)</li><li>Lower ink smoothing quality (Settings → Canvas &amp; Ink → Advanced Strokes → Ink Smoothing Quality)</li><li>Disable async ink smoothing</li><li>Check if the graphics driver is up to date</li></ol><h3 id="ink-not-smooth-jagged" tabindex="-1">Ink not smooth / jagged <a class="header-anchor" href="#ink-not-smooth-jagged" aria-label="Permalink to &quot;Ink not smooth / jagged&quot;">​</a></h3><ol><li>Make sure Advanced Bezier Smoothing is enabled</li><li>Check if Pen Tip Mode is set to &quot;Off&quot; — disabling it can make strokes more uniform</li><li>Set ink smoothing quality to &quot;High Quality&quot;</li></ol><h3 id="gestures-not-working" tabindex="-1">Gestures not working <a class="header-anchor" href="#gestures-not-working" aria-label="Permalink to &quot;Gestures not working&quot;">​</a></h3><ol><li>Make sure the gesture master toggle in settings is enabled</li><li>Check if you&#39;re using gestures in the correct mode (screen annotation mode and whiteboard mode gestures are configured independently)</li><li>Check if &quot;Pen Only&quot; mode is enabled — finger input is ignored in this mode</li><li>Check if other software (e.g., Windows Ink Workspace) is intercepting gestures</li></ol><h3 id="shape-recognition-inaccurate" tabindex="-1">Shape recognition inaccurate <a class="header-anchor" href="#shape-recognition-inaccurate" aria-label="Permalink to &quot;Shape recognition inaccurate&quot;">​</a></h3><ol><li>Make sure &quot;Enable Shape Recognition&quot; is enabled</li><li>Make sure the specific shape (rectangle/triangle/circle) recognition toggle is enabled</li><li>Adjust line straightening sensitivity — try lowering the sensitivity value for higher precision</li><li>Try to draw shapes in one continuous stroke, avoid breaks</li></ol><h2 id="performance-compatibility" tabindex="-1">Performance &amp; Compatibility <a class="header-anchor" href="#performance-compatibility" aria-label="Permalink to &quot;Performance &amp; Compatibility&quot;">​</a></h2><h3 id="high-cpu-memory-usage" tabindex="-1">High CPU / memory usage <a class="header-anchor" href="#high-cpu-memory-usage" aria-label="Permalink to &quot;High CPU / memory usage&quot;">​</a></h3><ol><li>Disable hardware acceleration</li><li>Lower ink smoothing quality</li><li>Disable async ink smoothing</li><li>Reduce log level (e.g., from &quot;Debug&quot; to &quot;Info&quot;)</li><li>Disable the floating window blocking feature (this feature adds performance overhead)</li><li>Check if other processes are conflicting with ICC-CE</li></ol><h3 id="conflicts-with-certain-software" tabindex="-1">Conflicts with certain software <a class="header-anchor" href="#conflicts-with-certain-software" aria-label="Permalink to &quot;Conflicts with certain software&quot;">​</a></h3><p>ICC-CE&#39;s floating window blocking feature can block floating windows from teaching software such as Seewo and Hitevision. If you encounter conflicts with other software, try disabling this feature or adjusting related settings.</p><h3 id="multi-monitor-support" tabindex="-1">Multi-monitor support <a class="header-anchor" href="#multi-monitor-support" aria-label="Permalink to &quot;Multi-monitor support&quot;">​</a></h3><p>ICC-CE supports multi-monitor environments. Enable multi-monitor related options in settings. If you experience canvas display issues, try enabling &quot;Multi-Monitor Canvas Fix&quot;.</p><h2 id="files-data" tabindex="-1">Files &amp; Data <a class="header-anchor" href="#files-data" aria-label="Permalink to &quot;Files &amp; Data&quot;">​</a></h2><h3 id="how-to-back-up-configuration-and-data" tabindex="-1">How to back up configuration and data <a class="header-anchor" href="#how-to-back-up-configuration-and-data" aria-label="Permalink to &quot;How to back up configuration and data&quot;">​</a></h3><p>Back up the entire <code>%AppData%\\InkCanvasForClass CE\\</code> directory. When reinstalling the system or migrating to a new computer, copy the backup data to the same path.</p><h3 id="how-to-completely-uninstall" tabindex="-1">How to completely uninstall <a class="header-anchor" href="#how-to-completely-uninstall" aria-label="Permalink to &quot;How to completely uninstall&quot;">​</a></h3><ul><li><strong>Installer</strong>: Settings → Apps → Installed apps → InkCanvasForClass CE → Uninstall</li><li><strong>Portable</strong>: Simply delete the entire folder</li></ul><p>Uninstallation does not automatically clear user configuration and ink archives. For complete cleanup, manually delete the <code>%AppData%\\InkCanvasForClass CE\\</code> directory.</p><h3 id="how-to-restore-default-settings" tabindex="-1">How to restore default settings <a class="header-anchor" href="#how-to-restore-default-settings" aria-label="Permalink to &quot;How to restore default settings&quot;">​</a></h3><p>Delete <code>%AppData%\\InkCanvasForClass CE\\Configs\\Settings.json</code>, and the program will generate a default configuration on next launch. It&#39;s recommended to back up the original file first.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><h3 id="how-to-switch-update-channels" tabindex="-1">How to switch update channels <a class="header-anchor" href="#how-to-switch-update-channels" aria-label="Permalink to &quot;How to switch update channels&quot;">​</a></h3><p>Change the &quot;Update Channel&quot; in settings. The Beta channel provides the fastest updates, while Release is the most stable.</p><h3 id="issues-after-cross-channel-switching" tabindex="-1">Issues after cross-channel switching <a class="header-anchor" href="#issues-after-cross-channel-switching" aria-label="Permalink to &quot;Issues after cross-channel switching&quot;">​</a></h3><p>When downgrading from Beta to Release, configuration entries written by the newer version may not be recognized by the older version. If issues occur, back up and delete the configuration file to let the program regenerate it.</p><h3 id="update-failed" tabindex="-1">Update failed <a class="header-anchor" href="#update-failed" aria-label="Permalink to &quot;Update failed&quot;">​</a></h3><ol><li>Check network connection</li><li>Try manually downloading the latest version installer</li><li>Check if the update channel setting is correct</li><li>Check the log file for detailed error information</li></ol><h2 id="how-to-get-help" tabindex="-1">How to Get Help <a class="header-anchor" href="#how-to-get-help" aria-label="Permalink to &quot;How to Get Help&quot;">​</a></h2><ul><li><strong>GitHub Issues</strong>: Submit issues on the project repository</li><li><strong>Log files</strong>: <code>%AppData%\\InkCanvasForClass CE\\Logs\\</code>, please attach logs when submitting issues</li><li><strong>Configuration export</strong>: If you need help troubleshooting, export your settings and share them with the developer</li></ul>',51))])}const q=r(u,[["render",c]]);export{b as __pageData,q as default};
